import "./card.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type CardProps = ComponentProps<"div">;

export function Card({ className, ...rest }: CardProps) {
  return <div className={cx("ns-card", className)} {...rest} />;
}

@layer components {
  .ns-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-5, 0.61rem);
    box-sizing: border-box;
    padding: var(--space-8, 1.19rem);
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 12%, transparent));
    border-radius: var(--radius, 0.4rem);
    background: var(--bg, #fff);
    color: var(--text-body, #444);
    box-shadow: none;
  }
}
